import{A as e}from"./UIcon.bed52dd6.js";import{g as o}from"./skills.e47faa77.js";const i=[{slug:"mamba-foley",color:"#5e95e3",description:"Recent advancements in deep learning have led to widespread use of techniques for audio content generation, notably employing Denoising Diffusion Probabilistic Models (DDPM) across various tasks. Among these, Foley Sound Synthesis is of particular interest for its role in applications for the creation of multimedia content. Given the temporal-dependent nature of sound, it is crucial to design generative models that can effectively handle the sequential modeling of audio samples. Selective State Space Models (SSMs) have recently been proposed as a valid alternative to previously proposed techniques, demonstrating competitive performance with lower computational complexity. In this paper, we introduce MambaFoley, a diffusion-based model that, to the best of our knowledge, is the first to leverage the recently proposed SSM known as Mamba for the Foley sound generation task. To evaluate the effectiveness of the proposed method, we compare it with a state-of-the-art Foley sound generative model using both objective and subjective analyses.",shortDescription:"Foley Sound Generation using Selective State-Space Models",links:[{to:"https://furiocolombo.github.io/mamba-foley/",label:"Website"},{to:"https://arxiv.org/abs/2409.09162",label:"Paper"},{to:"https://github.com/FurioColombo/mamba-foley",label:"GitHub"}],logo:e.mambaFoleyPaper,name:"MambaFoley",period:{from:new Date(2024,3,0),to:new Date(2024,10,10)},skills:o("python","DL","generative models","diffusion models","selective state-space models"),type:"ICASSP 2025 Paper"},{slug:"ForgerNFX",color:"#ff3e00",description:`This project is a real-time neural multi-effect guitar distortion, developed using the RTNeural framework on the Bela platform.
 The deep model is based on LSTM networks and performs time-domain filtering on the received audio inputs.
 The model is trained on audio samples of the same instrument recorded both with a clean tone and the distorted one.
 Two different pipelines are implemented, providing suitable dataset formats ready-to-use for the model training, depending on the nature of the data available.
 The effect runs on the Bela board and can be controlled thanks to a GUI, available through the Bela IDE.
 Code able to perform some performance evaluation testing and comparing the latency and sound quality is also available, together with specific tests on Bela’s performances.
 This project is a proof of concept for the potential of tiny machine learning in innovative real-time audio processing systems, encouraging further research and development of audio effects and other audio-related applications in this context.`,shortDescription:"A neural guitar distortion effect designed for guitar and running in hard real-time on Bela.",links:[{to:"https://github.com/FurioColombo/SeletectedTopics2023ForgerNFX",label:"GitHub"},{to:"https://youtu.be/2kOvCCvieIw",label:"Video Presentation"},{to:"https://youtu.be/tF_DCMwAfec",label:"Video Demo"}],logo:e.forgernfxLogo,name:"ForgerNFX",period:{from:new Date(2023,5,3),to:new Date(2023,8,1)},skills:o("torch","python","c","DL","ML"),type:"Polimi - MAE",screenshots:[{label:"ForgerNFX Pedal graphic interface",src:"https://raw.githubusercontent.com/FurioColombo/SeletectedTopics2023ForgerNFX/refs/heads/master/assets/forger_pedal_image.png"}]},{slug:"music-vae",color:"#ff3e00",description:`Our study is focused on investigating the presence of any correlations between the topological structure of the latent space and high-level features of the output. 
This project supplies a valid starting point for the systematic sampling of the pre-trained model of MusicVAE, a beta Variational AutoEncoder by Magenta. 
We offer ready-to-use tools for the analysis of the 2-bar and 16-bar pre-trained model configurations. 
We employ Latin Hypercube Sampling to perform latent space regularization, which leads to explicit control over the relation between the output’s characteristics and the locations of the samples within the embedding. 
The available tools automate sampling, output feature calculations and evaluation. 
The purpose of this work is to unveil the presence of possible correlations between the topological structure of the latent space and high level features of the output, which could be relevant for future works involving the refining of post hoc conditioning in generative models.`,shortDescription:"Our study is focused on investigating the presence of any correlations between the topological structure of the latent space and high-level features of the output.",links:[{to:"https://github.com/FurioColombo/MAEC-L04-Music-Generation?tab=readme-ov-file",label:"GitHub"},{to:"https://github.com/FurioColombo/MAEC-L04-Music-Generation/blob/main/assets/L04_Report.pdf",label:"Paper Report"}],logo:e.Unknown,name:"Deep Generative Human-Interpretable Musical Attributes Encoding",period:{from:new Date(2023,3,15),to:new Date(2023,6,14)},skills:o("tensorflow","python","DL","ML"),type:"Polimi - MAE"},{slug:"pixel-piano",color:"#5e95e3",description:"This project transforms the way we interact with musical instruments by combining wearable technology, computer vision, and real-time data processing. By using a glove embedded with pressure sensors and a camera-based hand tracking system, you can play a virtual piano on any flat surface, making music accessible and portable.",shortDescription:"The interactive virtual piano",links:[{to:"https://github.com/FurioColombo/PixelPiano",label:"GitHub"},{to:"https://github.com/FurioColombo/PixelPiano/blob/main/assets/CPAC%20-%20PixelPiano_presentation.pdf",label:"Presentation"},{to:"https://youtu.be/gYgQBFjvDSU",label:"Video Demo"}],logo:e.pixelPianoLogo,name:"PixelPiano",period:{from:new Date(2023,10,12),to:new Date(2024,6,10)},skills:o("python","Java","C"),type:"Polimi - MAE",screenshots:[{label:"Homepage",src:"https://raw.githubusercontent.com/FurioColombo/PixelPiano/refs/heads/main/assets/screenshots/home.png"},{label:"Mode Selection Page",src:"https://raw.githubusercontent.com/FurioColombo/PixelPiano/refs/heads/main/assets/screenshots/mode_selection_page.png"},{label:"Free Play Mode",src:"https://raw.githubusercontent.com/FurioColombo/PixelPiano/refs/heads/main/assets/screenshots/freeplay_page.png"},{label:"Piano Hero Mode",src:"https://raw.githubusercontent.com/FurioColombo/PixelPiano/refs/heads/main/assets/screenshots/pianohero_page.png"}]},{slug:"zenyth",color:"#5e95e3",description:`Web Application: https://furiocolombo.github.io/zenyth-polisint/

Zenyth PolisinT is a JavaScript semi-modular polyphonic synthesizer powered by Tone.js and implemented using the framework Vue.
Zenyth is designed as a playful yet powerful tool to discover modular synthesis. Its lighthearted exploration-based interface encourages users to discover its features by trying out all blocks and routing options.
 Zenyth PolisinT features four types of synthesis engines, a noise generator, three filter chains, and three effects chains. On top of that five dynamically assignable modulators and a main ADSR Envelope allow to shape the sound further and produce crazy noises.`,shortDescription:"Zenyth PolisinT is a JavaScript semi-modular polyphonic synthesizer powered by Tone.js and implemented using the framework Vue.",links:[{to:"https://furiocolombo.github.io/zenyth-polisint",label:"Synth"},{to:"https://github.com/FurioColombo/zenyth-polisint",label:"GitHub"},{to:"https://www.youtube.com/watch?v=3jTYMbAtMqI",label:"Presentation Video"},{to:"https://www.youtube.com/watch?v=cjMXcdHnGRU",label:"Video Demo"}],logo:e.zenythLogo,name:"Zenyth PolisinT",period:{from:new Date(2022,11,1),to:new Date(2023,2,15)},skills:o("js","vue","HTML","CSS"),type:"Polimi - MAE",screenshots:[{label:"Synth Page",src:"https://raw.githubusercontent.com/FurioColombo/zenyth-polisint/refs/heads/main/assets/zenith_polisint.png"}]},{slug:"harmmmlonizer",color:"#5e95e3",description:`HarMMMLonizer is a real-time harmonizer implemented in SuperCollider. 
The software implements a DSP system featuring mono input and stereo output. 
The DSP chain includes a delay line block which supports different feedback setups. Furthermore, a graphical user interface enables the musician to control available parameters, each specifically related to pitch shifting, delay effect and master. 

HarMMMLonizer supports three additional pitched voices to build the harmony, but a global variable within the code enables the programmer to change the number of voices. 
As the software is designed, this can be done without changing the software architecture.`,shortDescription:"HarMMMLonizer is a real-time harmonizer implemented in SuperCollider.",links:[{to:"https://github.com/FurioColombo/Harmmmlonizer---CMLS-HW1",label:"GitHub"},{to:"https://github.com/FurioColombo/Harmmmlonizer---CMLS-HW1/blob/main/Harmmmlonizer.pdf",label:"Report"},{to:"https://github.com/FurioColombo/Harmmmlonizer---CMLS-HW1/blob/main/Harmmmlonizer%20Presentation.pdf",label:"Presentation"},{to:"https://youtu.be/M7niXbSUGBo",label:"Video Demo"}],logo:e.Unknown,name:"HarMMMLonizer",period:{from:new Date(2022,3,15),to:new Date(2022,4,15)},skills:o("Supercollider","Audio Processing","DSP"),type:"Polimi - MAE",screenshots:[{label:"Graphic Interface",src:"https://raw.githubusercontent.com/FurioColombo/Harmmmlonizer---CMLS-HW1/refs/heads/main/assets/images/fullHarmonizerGui.png"}]},{slug:"oranjam",color:"#5e95e3",description:`OranJam is an instrument plugin which implements a polyphonic subtractive synthesizer. 

The software was implemented in C++ programming language with the aid of JUCE framework, a powerful cross-platform library which supports different operating systems (MacOS, Windows, Linux) and plugin standards available on the market today (VST, VST3, Audio Unit, Audio Unit V3, RTAS, AAX). 

The DSP chain includes several functional blocks: an oscillators bank, a white noise generator, an ADSR envelope, a filters bank and a LFO. 
A graphical user interface enables the user to control available parameters, such as Waveform for each oscillator, CutOff Frequency and Resonance for each filter.`,shortDescription:"OranJam is an instrument plugin which implements a polyphonic subtractive synthesizer.",links:[{to:"https://github.com/FurioColombo/CMLS-Homework2",label:"GitHub"},{to:"https://github.com/FurioColombo/CMLS-Homework2/blob/main/OranJam.pdf",label:"Report"},{to:"https://github.com/FurioColombo/CMLS-Homework2/blob/main/OranJam%20Presentation.pdf",label:"Presentation"}],logo:e.oranjamLogo,name:"OranJam",period:{from:new Date(2022,4,15),to:new Date(2022,5,14)},skills:o("C++","JUCE","CMake","Audio Processing"),type:"Polimi - MAE",screenshots:[{label:"Synth Graphic Interface",src:"https://raw.githubusercontent.com/FurioColombo/CMLS-Homework2/refs/heads/main/Assets/images/SubSynthGUI.png"}]},{slug:"padder",color:"#5e95e3",description:`Padder is a musical instrument based on a virtual pedal that, thanks to the interaction between the different blocks of its architecture, can generate chords that can be played in real time during a musical performance. 

This approach can be seen as a hands-free way to generate chords, instead of using a piano or a keyboard. For example, it is possible to play the chords with the foot, while you’re playing the guitar and singing at the same time. 
Thanks to the small dimensions of the Arduino board and the sensors, it’s also a more portable instrument than a keyboard or a piano. 
Moreover, by changing the synthesizer parameters, the musician can also create complex and very interesting pad-like sounds.`,shortDescription:"Padder is a musical instrument based on a virtual pedal that, thanks to the interaction between the different blocks of its architecture, can generate chords that can be played in real time during a musical performance.",links:[{to:"https://github.com/FurioColombo/Padder-CMLS-HW3",label:"GitHub"},{to:"https://github.com/FurioColombo/Padder-CMLS-HW3/blob/main/Padder.pdf",label:"Report"},{to:"https://github.com/FurioColombo/Padder-CMLS-HW3/blob/main/Padder%20Presentation.pdf",label:"Presentation"}],logo:e.padderLogo,name:"Padder",period:{from:new Date(2022,5,15),to:new Date(2022,6,15)},skills:o("C++","Java","Supercollider","Arduino","Audio Processing"),type:"Polimi - MAE",screenshots:[{label:"Graphic Interface",src:"https://raw.githubusercontent.com/FurioColombo/Padder-CMLS-HW3/refs/heads/main/Assets/Images/seaLandscape.png"}]},{slug:"terminal-text-editor",color:"#5e95e3",description:`Algorithms and Principles of Informatics Project 2020 - Optimized CLI Text Editor.

Text editor with a command line interface, written from scratch in C to pass a test suite under tight time and memory constraints.

 The main.c opens a CLI based text editor with a few possible commands, such as writing, deleting and undoing an arbitrary number of commands. The project was completed in about a week of work in summer 2020, then reviewed and cleaned up before being submitted for evaluation.`,shortDescription:"Text editor with a command line interface, written from scratch in C and heavily optimized.",links:[],logo:e.Unknown,name:"Terminal Text Editor",period:{from:new Date(2020,5,15),to:new Date(2020,6,15)},skills:o("C"),type:"Polimi - Computer Engineering"}],n="Projects";export{i,n as t};
